package in.finseq.insurance;
import android.app.*;import android.content.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;
public class PoliciesActivity extends FinseqActivity{
 LinearLayout root,list;EditText search;JSONArray policies=new JSONArray();String policyFilter="",month="",period="";
 public void onCreate(Bundle b){super.onCreate(b);policyFilter=getIntent().getStringExtra("policy_filter");if(policyFilter==null)policyFilter="";month=getIntent().getStringExtra("month");if(month==null)month="";period=getIntent().getStringExtra("period");if(period==null)period="";root=Ui.column(this);Ui.appHeader(root,this,"Policies");LinearLayout body=Ui.contentColumn(this);root.addView(body);search=Ui.input(this,"Search policy, customer, insurer or vehicle");body.addView(search);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){renderList();}public void afterTextChanged(Editable e){}});setContentView(Ui.scroll(this,root));load();}
 void load(){Ui.run(this,()->{try{JSONObject j=ApiClient.get(this,"/api/v1/sync");policies=j.optJSONArray("policies");if(policies==null)policies=new JSONArray();Ui.ui(this,this::renderList);}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
 void renderList(){list.removeAllViews();String q=search.getText().toString().trim().toLowerCase();int count=0;double total=0;for(int i=0;i<policies.length();i++){JSONObject p=policies.optJSONObject(i);if(p==null)continue;if(policyFilter.equals("inspection")&&p.optDouble("inspection")<=0)continue;String issued=p.optString("issue_date");if(issued.isEmpty())issued=p.optString("start_date");if(!month.isEmpty()&&!issued.startsWith(month))continue;if(!DashboardPeriod.contains(period,issued))continue;String hay=(p.optString("policy_number")+" "+p.optString("customer")+" "+p.optString("insurer")+" "+p.optString("vehicle")).toLowerCase();if(!q.isEmpty()&&!hay.contains(q))continue;count++;total+=p.optDouble("premium");LinearLayout c=Ui.card(this);c.addView(Ui.text(this,p.optString("customer","Client"),17,true));c.addView(Ui.sub(this,p.optString("policy_number")+" · "+p.optString("insurer")));c.addView(Ui.sub(this,p.optString("type")+" / "+p.optString("subtype")+(p.optString("vehicle").isEmpty()?"":" · "+p.optString("vehicle"))));c.addView(Ui.text(this,"Expiry: "+p.optString("expiry_date")+" · Premium: "+Ui.money(p.optDouble("premium")),14,true));TextView status=Ui.badge(this,p.optString("status","Recorded"),p.optDouble("due")>0?Ui.RED:Ui.GREEN);c.addView(status);LinearLayout buttons=new LinearLayout(this);buttons.setOrientation(LinearLayout.HORIZONTAL);Button preview=Ui.button(this,"Preview PDF");Button share=Ui.greenButton(this,"Open Details");buttons.addView(preview,new LinearLayout.LayoutParams(0,-2,1));buttons.addView(share,new LinearLayout.LayoutParams(0,-2,1));c.addView(buttons);int id=p.optInt("id");preview.setEnabled(p.optBoolean("has_pdf"));preview.setOnClickListener(v->startActivity(new Intent(this,PdfPreviewActivity.class).putExtra("policy_id",id)));share.setOnClickListener(v->startActivity(new Intent(this,PolicyDetailActivity.class).putExtra("policy_id",id)));list.addView(c);}TextView summary=Ui.sub(this,count+" policy record(s) · Shown Gross Premium: "+Ui.money(total));list.addView(summary,0);}
}
